std::vector<uint8_t> file_bytes(const std::filesystem::path &path){std::ifstream f(path,std::ios::binary);if(!f)throw std::runtime_error("Missing native package artifact");return {std::istreambuf_iterator<char>(f),{}};}
void endpoint(Document &doc){if(!doc.wait_asset(std::chrono::seconds(180))||!doc.wait_mesh(std::chrono::seconds(180)))throw std::runtime_error("Combined native graphics endpoint timed out");if(!doc.frame().state->error.empty())throw std::runtime_error(doc.frame().state->error);}
void pixels(const std::filesystem::path &path,const Pixels &data){std::ofstream f(path,std::ios::binary);f.write(reinterpret_cast<const char*>(data.data()),std::streamsize(data.size()));if(!f)throw std::runtime_error("Cannot retain consumer pixels");}
uint64_t explicit_key(const Scene &s){uint64_t selected=0;for(const auto &o:s.objects())if(o.material_bindings&&o.material_bindings->key_derivation&&o.material_bindings->key_derivation->uses_explicit_mirror()){if(selected)throw std::runtime_error("Combined fixture needs one explicit Mirror owner");selected=o.id;}if(!selected)throw std::runtime_error("No genuine explicit Mirror owner");return selected;}
void pose(Scene &s,uint64_t selected,int mode,float weight){const auto group=s.object(selected).group;for(const auto &item:s.objects())if(item.id==selected||(group&&item.group==group)){if(!item.deformation)continue;auto d=*item.deformation;
 // The small genuine seam fixture has morphs but no Skeleton.
 if(d.skeleton){d.pose.clear();for(const auto &b:d.skeleton->bones)d.pose.push_back(b.rest);if(mode&&d.humanoid){const auto hips=d.humanoid->joints.at("hips"),spine=d.humanoid->joints.at("spine");d.pose[hips].scale={1.15f,.9f,.7f};d.pose[spine].scale={.85f,1.05f,1.2f};d.pose[spine].rotation={std::cos(.08f),0,0,std::sin(.08f)};}}
 if(d.morphs){d.morph_weights.assign(d.morphs->targets.size(),0);if(item.id==selected){if(d.morphs->targets.size()>1)d.morph_weights[0]=.2f;d.morph_weights.back()=weight;}}s.set_deformation(item.id,std::move(d));}}
float independent_positions(const MeshSnapshot &native,const frame_consumer::Renderer &consumer){std::vector<Vec3> a=native.mesh.positions,b;for(const auto &[id,positions]:consumer.world_positions)b.insert(b.end(),positions.begin(),positions.end());if(a.empty()||b.empty())throw std::runtime_error("Independent geometry oracle has no corners");
 auto sort=[](std::vector<Vec3> &v){std::sort(v.begin(),v.end(),[](Vec3 x,Vec3 y){return x.x<y.x;});};sort(a);sort(b);float error=0;
 auto measure=[&](const std::vector<Vec3> &from,const std::vector<Vec3> &to){for(auto p:from){float nearest=std::numeric_limits<float>::infinity();auto first=std::lower_bound(to.begin(),to.end(),p.x-1e-5f,[](Vec3 v,float x){return v.x<x;});for(auto i=first;i!=to.end()&&i->x<=p.x+1e-5f;++i)nearest=std::min(nearest,length(p-*i));error=std::max(error,nearest);}};measure(a,b);measure(b,a);return error;
}
