 std::filesystem::create_directories(out);const auto input_bytes=file_bytes(input);auto source=Scene::load(input);const auto original=source.encode();const uint64_t key=explicit_key(source),group=source.object(key).group;const auto derivation=source.object(key).material_bindings->key_derivation;check(source.object(key).shape_source&&derivation->valid_owner(derivation),"Combined input owns actual Scene29 Mirror and first-shape authority");
 size_t hidden_paint=0,visible=0;for(const auto &o:source.objects()){const bool keep=o.id==key||(group&&o.group==group);source.object(o.id).visible=keep;visible+=keep;if(!keep&&o.painted&&o.painted->source_sampling_prepared()){check(o.painted->valid_source_sampling_attachment(),"Hidden separate namespace owns authenticated Source4 paint");++hidden_paint;}}
 check(hidden_paint>0&&(!avatar||visible>=19),"Focused native view keeps the whole avatar and hides only separate namespace data");// The small fixture's independently inspected key is purely local Z (.01..05).
