 doc.authored_shading();endpoint(doc);const auto authored_frame=doc.frame();check(!authored_frame.surface->pbr_view&&!authored_frame.state->pbr_view&&authored_frame.surface->view_epoch==authored_frame.state->view_epoch,"Actual authored command publishes the immutable MToon role and epoch");fbo.bind();const auto authored=key_draw(renderer,authored_frame.surface);pixels(out/(stem+".authored-native.rgba"),authored);opened.authored_shading();endpoint(opened);fbo.bind();check(delta(authored,key_draw(renderer,opened.frame().surface))==0,"Package Open retains exact native authored MToon pixels without changing source data");
