int main(int argc,char **argv)try{
 if(argc<3)return 2;bool hardware=std::string_view(argv[argc-1])=="--hardware";if(hardware)--argc;NativeGraphics graphics;const std::string vendor=reinterpret_cast<const char*>(glGetString(GL_VENDOR)),device=reinterpret_cast<const char*>(glGetString(GL_RENDERER));std::cout<<"GL_VENDOR "<<vendor<<"\nGL_RENDERER "<<device<<std::endl;const bool software=device.find("llvmpipe")!=std::string::npos||device.find("softpipe")!=std::string::npos;check(hardware?(vendor.find("Intel")!=std::string::npos&&device.find("Arc")!=std::string::npos&&device.find("A770")!=std::string::npos&&device.find("UHD")==std::string::npos&&!software):software,"Combined package consumer uses the explicitly requested graphics device");Fbo fbo;SurfaceRenderer renderer;renderer.set_frame_time(0);frame_consumer::Renderer consumer; // Persistent throughout all GL calls; never pending-delete program reuse.
 for(int i=2;i<argc;++i){auto probe=Scene::load(argv[i]);const auto key=explicit_key(probe);const auto deformation=probe.object(key).deformation;const bool avatar=bool(deformation&&deformation->skeleton&&deformation->humanoid&&deformation->skeleton->bones.size()>=15);combined(argv[i],std::filesystem::path(argv[1])/("case"+std::to_string(i-2)),avatar,renderer,fbo,consumer);}std::cout<<"PASS "<<checks<<" combined native package render checks\n";return 0;
}catch(const std::exception &e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
